def ensure_all_group(inventory: Any) -> object {
    if ("all" not in inventory) {
        inventory["all"] = {"children": {}, "hosts": {}};
    }
    all_group = inventory["all"];
    if ("children" not in all_group) {
        all_group["children"] = {};
    }
    if ("hosts" not in all_group) {
        all_group["hosts"] = {};
    }
    return all_group;
}

